using System;using System.Drawing;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmRefundManagement:StyledForm { DataGridView g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells};public FrmRefundManagement(){Text="Refund Management";Size=new Size(1000,550);var p=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=55};foreach(var s in new[]{"Approved","Processing","Completed","Rejected"}){string status=s;var b=new Button{Text=status,Width=110};b.Click+=delegate{if(g.CurrentRow!=null&&g.Columns.Contains("RefundId")){new RefundQuery().Change(Convert.ToInt32(g.CurrentRow.Cells["RefundId"].Value),status);LoadData();}};p.Controls.Add(b);}Controls.Add(g);Controls.Add(p);LoadData();}void LoadData(){g.DataSource=QueryUtil.Table("SELECT R.RefundId,A.ApplicationNo,S.StudentName,P.PaidAmount,R.RefundEligibility,R.RefundAmount,R.RefundReason,R.RefundStatus,R.RefundDate,R.RefundReference FROM ((Refunds R INNER JOIN Applications A ON R.ApplicationId=A.ApplicationId) INNER JOIN Students S ON A.StudentId=S.StudentId) INNER JOIN Payments P ON R.PaymentId=P.PaymentId");} } }
